#!/usr/bin/env node
// Generates the typed models and one method per operation of the TypeScript SDK from ../openapi.json
// (the live spec, https://api.pitchmentor.net/v1/openapi.json). Hand-written transport (retries, errors,
// pagination, webhooks) lives next to the generated file. Run: scripts/regen.sh (download + generate)
// or node codegen/generate.mjs (generate from the committed openapi.json).
import { readFileSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const spec = JSON.parse(readFileSync(join(root, "openapi.json"), "utf8"));
// `ErrorResponse` is modelled by each SDK's hand-written error class
const { ErrorResponse: _errorSchema, ...schemas } = spec.components.schemas;

// ── IR ────────────────────────────────────────────────────

const refName = (ref) => ref.split("/").pop();
const isList = (s) => s?.type === "object" && s.properties?.data?.type === "array" && "next_cursor" in (s.properties ?? {});
const listItem = (s) => s.properties.data.items;

const ops = [];
for (const [path, methods] of Object.entries(spec.paths)) {
  for (const [method, op] of Object.entries(methods)) {
    const params = op.parameters ?? [];
    const ok = Object.entries(op.responses).find(([code]) => code.startsWith("2"))[1];
    const query = params.filter((p) => p.in === "query");
    ops.push({
      id: op.operationId,
      method: method.toUpperCase(),
      path,
      tag: op.tags?.[0] ?? "",
      summary: op.summary ?? "",
      description: op.description ?? "",
      scope: op["x-required-scope"] ?? null,
      pathParams: params.filter((p) => p.in === "path").map((p) => p.name),
      query,
      body: op.requestBody?.content?.["application/json"]?.schema ?? null,
      response: ok.content?.["application/json"]?.schema ?? null,
      csv: !!ok.content?.["text/csv"],
      paginated: query.some((p) => p.name === "cursor"),
      destructive: op["x-destructive"] === true, // flagged in docs, CLI (--yes) and MCP (destructiveHint)
    });
  }
}
// Events an endpoint can subscribe to (webhook.test is in `webhooks` but is only sent by testWebhookEndpoint)
const subscribableEvents = schemas.WebhookEndpoint.properties.events.items.enum;
const webhookEvents = Object.values(spec.webhooks ?? {}).map((w) => {
  const s = w.post.requestBody.content["application/json"].schema;
  return { type: s.properties.type.const, data: s.properties.data };
});

// ── naming ────────────────────────────────────────────────

const upper = (s) => s[0].toUpperCase() + s.slice(1);
const snake = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1_$2").replace(/-/g, "_").toLowerCase();
const goName = (s) =>
  s
    .split(/[_-]/)
    .map(upper)
    .join("")
    .replace(/Id(?=[A-Z]|$)/g, "ID")
    .replace(/Url(?=[A-Z]|$)/g, "URL");
const docLines = (op) =>
  [
    op.summary + (op.summary.endsWith(".") ? "" : "."),
    op.description.replace(/\n*Requires scope `[^`]+`\.$/, "").trim(),
    op.scope ? `Requires scope \`${op.scope}\`.` : "",
    op.destructive ? "DESTRUCTIVE: cannot be undone." : "",
  ].filter(Boolean);
const types = (s) => [s.type].flat().filter(Boolean);
const nullable = (s) => types(s).includes("null");
const HEADER = "Code generated by codegen/generate.mjs from openapi.json. DO NOT EDIT.";

// ── TypeScript ────────────────────────────────────────────

function ts(s, ind = "") {
  if (!s || Object.keys(s).filter((k) => k !== "description").length === 0) return "unknown";
  if (s.$ref) return refName(s.$ref);
  if (s.allOf) return s.allOf.map((x) => ts(x, ind)).join(" & ");
  if (s.const !== undefined) return JSON.stringify(s.const);
  const t = types(s);
  if (s.enum) return [...s.enum.map((v) => JSON.stringify(v)), ...(t.includes("null") ? ["null"] : [])].join(" | ");
  if (t.length > 1) return t.map((x) => ts({ ...s, type: x }, ind)).join(" | ");
  switch (t[0]) {
    case "string":
      return "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "null":
      return "null";
    case "array": {
      const item = ts(s.items, ind);
      return /^[\w.]+$/.test(item) ? `${item}[]` : `Array<${item}>`;
    }
    case "object":
      if (isList(s)) return `Page<${ts(listItem(s), ind)}>`;
      if (!s.properties) return "Record<string, unknown>";
      return tsObject(s, ind);
  }
  return "unknown";
}

function tsObject(s, ind) {
  const req = new Set(s.required ?? []);
  const lines = Object.entries(s.properties).map(([k, v]) => {
    const doc = v.description ? `${ind}  /** ${v.description} */\n` : "";
    const key = /^[A-Za-z_$][\w$]*$/.test(k) ? k : JSON.stringify(k);
    return `${doc}${ind}  ${key}${req.has(k) ? "" : "?"}: ${ts(v, ind + "  ")};`;
  });
  if (s.additionalProperties) lines.push(`${ind}  [key: string]: unknown;`);
  return `{\n${lines.join("\n")}\n${ind}}`;
}

const inlineResponse = (op) => op.response?.type === "object" && op.response.properties && !isList(op.response);

function tsResult(op) {
  const json = !op.response ? "unknown" : inlineResponse(op) ? `${upper(op.id)}Response` : ts(op.response);
  return op.csv ? `${json} | string` : json;
}

function genTs() {
  const out = [`// ${HEADER}`, `import type { Page, RequestOptions } from "./core.js";`, ""];
  for (const [name, s] of Object.entries(schemas)) {
    if (s.description) out.push(`/** ${s.description} */`);
    out.push(s.type === "object" && s.properties ? `export interface ${name} ${tsObject(s, "")}` : `export type ${name} = ${ts(s)};`, "");
  }
  for (const op of ops) {
    if (op.query.length) {
      out.push(`export interface ${upper(op.id)}Query {`);
      for (const p of op.query) {
        if (p.description) out.push(`  /** ${p.description} */`);
        out.push(`  ${p.name}${p.required ? "" : "?"}: ${ts(p.schema)};`);
      }
      out.push("}", "");
    }
    if (op.body) out.push(`export type ${upper(op.id)}Body = ${ts(op.body)};`, "");
    if (inlineResponse(op)) out.push(`export interface ${upper(op.id)}Response ${tsObject(op.response, "")}`, "");
  }
  out.push(`export const WEBHOOK_EVENT_TYPES = ${JSON.stringify(subscribableEvents)} as const;`, "");
  out.push("/** A verified webhook payload. `webhook.test` is sent by testWebhookEndpoint. */");
  out.push("export type WebhookEvent =");
  out.push(...webhookEvents.map((e) => `  | { type: ${JSON.stringify(e.type)}; timestamp: string; data: ${ts(e.data)} }`));
  out[out.length - 1] += ";";
  out.push("");

  // Operation metadata: drives the CLI and MCP server.
  out.push("export interface OperationMeta {");
  out.push('  method: "GET" | "POST" | "PATCH" | "DELETE";');
  out.push("  path: string;\n  tag: string;\n  summary: string;\n  description: string;\n  scope: string | null;");
  out.push("  pathParams: readonly string[];");
  out.push("  /** JSON Schema of the query string (object), or null. */\n  query: Record<string, unknown> | null;");
  out.push("  /** JSON Schema of the request body, or null. */\n  body: Record<string, unknown> | null;");
  out.push("  paginated: boolean;\n  destructive: boolean;\n  csv: boolean;\n}", "");
  out.push("export const operations = {");
  for (const op of ops) {
    const query = op.query.length
      ? {
          type: "object",
          properties: Object.fromEntries(op.query.map((p) => [p.name, { ...p.schema, ...(p.description ? { description: p.description } : {}) }])),
          ...(op.query.some((p) => p.required) ? { required: op.query.filter((p) => p.required).map((p) => p.name) } : {}),
        }
      : null;
    const meta = {
      method: op.method,
      path: op.path,
      tag: op.tag,
      summary: op.summary,
      description: docLines(op).slice(1).join("\n\n"),
      scope: op.scope,
      pathParams: op.pathParams,
      query,
      body: op.body,
      paginated: op.paginated,
      destructive: op.destructive,
      csv: op.csv,
    };
    out.push(`  ${op.id}: ${JSON.stringify(meta)},`);
  }
  out.push("} as const satisfies Record<string, OperationMeta>;", "");
  out.push("export type OperationId = keyof typeof operations;", "");

  out.push("/** One method per API operation; transport is implemented by PitchMentor. */");
  out.push("export abstract class Operations {");
  out.push("  protected abstract request<T>(method: string, path: string, options?: RequestOptions & { query?: object; body?: unknown }): Promise<T>;");
  out.push("  protected abstract paginate<T>(fetchPage: (cursor?: string) => Promise<Page<T>>): AsyncGenerator<T>;");
  for (const op of ops) {
    const args = op.pathParams.map((p) => `${p}: string`);
    const pass = [];
    if (op.body) {
      args.push(`body: ${upper(op.id)}Body`);
      pass.push("body");
    }
    if (op.query.length) {
      args.push(`query: ${upper(op.id)}Query${op.query.some((p) => p.required) ? "" : " = {}"}`);
      pass.push("query");
    }
    args.push("options?: RequestOptions");
    const path = "`" + op.path.replace(/\{(\w+)\}/g, "${encodeURIComponent($1)}") + "`";
    out.push("", "  /**", ...docLines(op).flatMap((l) => l.split("\n")).map((l) => `   * ${l}`), "   */");
    out.push(`  ${op.id}(${args.join(", ")}): Promise<${tsResult(op)}> {`);
    out.push(`    return this.request(${JSON.stringify(op.method)}, ${path}, { ${[...pass, "...options"].join(", ")} });`);
    out.push("  }");
    if (op.paginated) {
      const item = ts(listItem(op.response));
      const iterArgs = [...op.pathParams.map((p) => `${p}: string`), `query: Omit<${upper(op.id)}Query, "cursor"> = {}`, "options?: RequestOptions"];
      out.push("", `  /** Iterates every item of {@link ${op.id}}, fetching pages as needed. */`);
      out.push(`  ${op.id}Iter(${iterArgs.join(", ")}): AsyncGenerator<${item}> {`);
      out.push(`    return this.paginate((cursor) => this.${op.id}(${[...op.pathParams, "{ ...query, cursor }", "options"].join(", ")}));`);
      out.push("  }");
    }
  }
  out.push("}", "");
  writeFileSync(join(root, "src/generated.ts"), out.join("\n"));
}

genTs();
console.error(`generated ${ops.length} operations, ${Object.keys(schemas).length} schemas, ${webhookEvents.length} webhook events`);
